import{_ as t,o as i,c as n,a5 as o}from"./chunks/framework.CsGesDJn.js";const m=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"feature/admin-management/3-10-9-deactive-user/report3_spec_en.md","filePath":"feature/admin-management/3-10-9-deactive-user/report3_spec_en.md"}'),a={name:"feature/admin-management/3-10-9-deactive-user/report3_spec_en.md"};function r(s,e,l,c,d,u){return i(),n("div",null,[...e[0]||(e[0]=[o("<p><strong>3.10.9 Deactive User (Tiered Sanctions: Flag / Deactivate)</strong></p><p><strong>Function Trigger</strong></p><p>Begins when an Administrator (ADMIN) clicks &quot;Sanction / Deactivate&quot; from a user profile view (/admin/users/:id).</p><p><strong>Function Description</strong></p><ul><li><strong>Actors / Roles</strong>: ADMIN. Platform Administrator enforcing compliance sanctions against violating user accounts.</li><li><strong>Purpose</strong>: Apply a publishing flag or confirm a 30-day whole-account deactivation. Restore sanctioned accounts automatically after 30 days and send email.</li><li><strong>Interface</strong>: User Sanction &amp; Deactivation Modal Dialog (SCR-ADM-09), displaying account summary, active strike counters, 2 sanction tier radio options, and mandatory justification input.</li><li><strong>Data Processing</strong>: RED/three active ORANGE creates a review request. Admin inspects evidence and confirms DEACTIVATE with justification; then set deactivatedAt/reactivateAt=deactivatedAt+30 days, revoke all sessions/tokens and block account access. An idempotent background job restores ACTIVE at expiry and sends email; no second Admin approval is required.</li></ul><p><strong>Screen Layout</strong></p><p>Figure — User Sanction &amp; Deactivation Modal Dialog (SCR-ADM-09):</p><ul><li>Left/Header: Modal title &quot;Account Sanction &amp; Deactivation&quot;, warning triangle icon (orange for Flag) or padlock icon (red for Deactivate), and target User ID display.</li><li>Center: User summary, active YELLOW/ORANGE/RED counters, review request/evidence, FLAG or DEACTIVATE choice, reason and confirmation checkbox. Before locking a sole Owner, explain that members continue existing permissions while Owner-only operations wait. Show sanction start, automatic restoration time and review status.</li><li>Buttons: Button &quot;Cancel&quot;, Primary Action Button (Orange &quot;Confirm Flag&quot; or Red &quot;Confirm Deactivate&quot;).</li><li>Footer: Mandatory rule notice: &quot;Administrators cannot self-sanction or sanction peer Administrators. All user posts and PayOS billing data remain 100% preserved in database.&quot;</li></ul><p><strong>Function Details</strong></p><ul><li><p><strong>Data Specifications</strong></p><ul><li><strong>Input required</strong>: userId, sanctionType (FLAG/DEACTIVATE), reason; DEACTIVATE requires explicit Admin confirmation and review evidence.</li><li><strong>Input optional</strong>: sanctionRequestId, linkedStrikeIds, evidence references.</li><li><strong>System data</strong>: adminId, target systemRole/status, active strikes, review state, deactivatedAt, reactivateAt, restoredAt, email delivery status.</li><li><strong>Output</strong>: Sanction result payload { userId, status: &quot;FLAGGED&quot; | &quot;DEACTIVATED&quot;, activeStrikes } with HTTP 200 OK.</li></ul></li><li><p><strong>Business Rules</strong></p><ul><li><strong>BR-63</strong>: Only ADMIN confirms account deactivation. RED or three active ORANGE creates a pending review, not an automatic account lock. Revalidate evidence at confirmation; stale or duplicate requests do not duplicate sanctions.</li><li><strong>BR-94</strong>: FLAGGED permits login but requires ADMIN review for new and already scheduled publications. DEACTIVATED blocks the entire account for 30 days from confirmed sanction.</li><li><strong>BR-06</strong>: DEACTIVATED is enforced on login, refresh and authenticated operations; a previously issued token must not preserve access.</li><li><strong>BR-22</strong>: Revoke every active session and access/refresh token at deactivation. Restoration requires a fresh login; revoked tokens do not become valid again.</li><li><strong>BR-23</strong>: Sole Agency/Workspace Owners may receive profile edits, strikes, flags and confirmed 30-day account deactivation. Other members retain their existing permissions; Owner-only operations wait until restoration. Do not suspend the whole Agency or transfer ownership automatically. Agency ownership is separate from system role.</li><li><strong>BR-35</strong>: Admin cannot self-sanction or sanction peer ADMIN accounts.</li><li><strong>BR-96</strong>: At reactivateAt, automatically restore ACTIVE and send reopening email without Admin approval. Strike cleanup cannot unlock early. Preserve strike history; expired sanctions do not revive old strikes. Email failure is retried without undoing restoration. Never restore DELETED or unrelated legacy SUSPENDED records.</li><li><strong>BR-92</strong>: Preserve all user, Agency, publication and billing data; no hard-delete.</li><li><strong>BR-16</strong>: Audit review, confirmation, session revocation and automatic restoration with linked evidence and timestamps.</li></ul></li><li><p><strong>Validation</strong></p><ul><li>Missing ADMIN, self-sanction or peer-admin sanction → MSG39.</li><li>Unknown user/request → MSG38; missing reason/confirmation → MSG02.</li><li>Sole Owner is allowed after impact notice and Admin confirmation; no MSG92 rejection solely for ownership.</li><li>Already resolved request or already deactivated account → conflict/idempotent existing result; do not restart the penalty accidentally.</li><li>Deactivation completed → MSG91.</li></ul></li></ul><p><strong>Functionalities</strong></p><ul><li><p><strong>Normal Flow</strong></p><ol><li>RED/three active ORANGE opens a review request; account is not automatically deactivated.</li><li>Admin reviews strikes/evidence and chooses FLAG or confirms DEACTIVATE with reason.</li><li>Validate self/peer protections and current state; show sole Owner impact when applicable.</li><li>Apply the confirmed sanction once. For DEACTIVATE, store 30-day deadline and revoke all sessions/tokens; send sanction email and audit.</li><li>At the deadline, background processing verifies the same sanction is due and restores ACTIVE automatically.</li><li>Record restoration and send reopening email; the user logs in again with fresh credentials/session.</li></ol></li><li><p><strong>Abnormal Cases</strong></p><ul><li>2.a1: Admin does not confirm → request remains unresolved; no deactivation.</li><li>3.a1: Self/peer-admin target → MSG39; ownership alone does not reject the sanction.</li><li>4.a1: Repeated submission → existing result; no duplicate strike or restarted penalty.</li><li>5.a1: Worker downtime → catch up due sanctions after recovery; never unlock before deadline.</li><li>6.a1: Email failure → retry notification; account remains restored. A different current sanction or DELETED state is not overwritten.</li></ul></li></ul><p><strong>Post-Conditions</strong></p><ul><li>Confirmed FLAGGED users retain sessions with ADMIN publishing gate; confirmed DEACTIVATED users lose all account access.</li><li>The 30-day sanction deadline is persisted and automatically restores ACTIVE when due, with email and audit.</li><li>Agency members continue their permissions; no automatic ownership transfer or Agency-wide suspension occurs.</li><li>All data and sanction/strike history remain intact.</li></ul>",14)])])}const g=t(a,[["render",r]]);export{m as __pageData,g as default};
